import math

def sharpe_se(sr, n, skew, kurt):
    return math.sqrt((1 - skew * sr + (kurt - 1) / 4 * sr ** 2) / (n - 1))

def psr(sr, sr_benchmark, n, skew, kurt):
    z = (sr - sr_benchmark) / sharpe_se(sr, n, skew, kurt)
    return round(0.5 * (1 + math.erf(z / math.sqrt(2))), 4)

