widget.solution:
import math
from statistics import NormalDist

EULER_GAMMA = 0.5772156649015329

def expected_max_sharpe(n_trials, var_trials):
    if n_trials <= 1:
        return 0.0
    inv = NormalDist().inv_cdf
    g = EULER_GAMMA
    return math.sqrt(var_trials) * ((1 - g) * inv(1 - 1 / n_trials) + g * inv(1 - 1 / (n_trials * math.e)))

def dsr(sr, n, skew, kurt, n_trials, var_trials):
    return psr(sr, expected_max_sharpe(n_trials, var_trials), n, skew, kurt)
